using HelpDeskLite.Api.Contracts;using HelpDeskLite.Api.Data;using HelpDeskLite.Api.Domain;using HelpDeskLite.Api.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace HelpDeskLite.Api.Controllers;
[ApiController,Route("api/manager"),Authorize(Roles=AppRoles.Manager)]public sealed class ManagerController(ApplicationDbContext db,UserManager<ApplicationUser> users,TicketService service):ControllerBase{[HttpGet("summary")]public async Task<ManagerSummaryDto> Summary(CancellationToken ct){var open=await db.Tickets.CountAsync(x=>x.Status==TicketStatus.Open,ct);var unassigned=await db.Tickets.CountAsync(x=>x.AssignedToUserId==null,ct);var progress=await db.Tickets.CountAsync(x=>x.Status==TicketStatus.InProgress,ct);var resolved=await db.Tickets.CountAsync(x=>x.Status==TicketStatus.Resolved,ct);var agents=await users.GetUsersInRoleAsync(AppRoles.SupportAgent);var activeCounts=await db.Tickets.AsNoTracking().Where(x=>x.AssignedToUserId!=null&&x.Status!=TicketStatus.Resolved).GroupBy(x=>x.AssignedToUserId!).Select(group=>new{UserId=group.Key,Count=group.Count()}).ToDictionaryAsync(x=>x.UserId,x=>x.Count,ct);var workload=agents.Select(agent=>new WorkloadDto(agent.Id,agent.DisplayName,activeCounts.GetValueOrDefault(agent.Id))).ToList();var all=await service.QueryAsync(new(null,null,null,null),null,false,ct);return new(open,unassigned,progress,resolved,workload,all.Take(4).ToList(),all.Where(x=>x.AssignedTo is null||x.Priority==TicketPriority.High).Take(3).ToList());}}
